//! Secure credential storage backed by the OS keychain.
//!
//! Platform backends:
//! - macOS: Apple Keychain (`apple-native` feature on the `keyring` crate)
//! - Windows: Credential Manager + DPAPI (`windows-native`)
//! - Linux: Secret Service / GNOME Keyring / KWallet (`sync-secret-service`)
//!
//! Entries are scoped by `(service, account)`. `service` is typically
//! the app's reverse-DNS identifier; `account` distinguishes multiple
//! credentials for the same service (multiple users, API keys, etc.).
//!
//! Dispatch is generated by `#[tynd::handler]` (U10) — typed per-arg
//! deser collapses the `args.get("...").and_then(Value::as_str)` chain
//! every method used to repeat.

use keyring::Entry;

use crate::{ipc_error::IpcError, tynd};

/// Marker type for the `#[tynd::handler]` dispatch table.
#[derive(Debug, Default)]
pub struct KeyringApi;

#[tynd::handler(api = "keyring")]
impl KeyringApi {
    /// Store `password` in the OS keychain under `(service, account)`.
    /// Returns `null` on success — wire shape stays consistent with
    /// the get/delete methods that legitimately return `null` for the
    /// "not present" case.
    pub fn set(service: String, account: String, password: String) -> Result<(), String> {
        new_entry("set", &service, &account)?
            .set_password(&password)
            .map_err(|e| IpcError::new("keyring", "set", e).into_string())
    }

    /// Read the password stored under `(service, account)`. Returns
    /// `null` when there's no matching entry — keychain "not found"
    /// is a normal case for first-run flows, not an error.
    pub fn get(service: String, account: String) -> Result<Option<String>, String> {
        match new_entry("get", &service, &account)?.get_password() {
            Ok(s) => Ok(Some(s)),
            Err(keyring::Error::NoEntry) => Ok(None),
            Err(e) => Err(IpcError::new("keyring", "get", e).into_string()),
        }
    }

    /// Delete the entry stored under `(service, account)`. Returns
    /// `true` when an entry was removed, `false` when no entry was
    /// present — symmetric with `get`'s null-on-missing shape.
    pub fn delete(service: String, account: String) -> Result<bool, String> {
        match new_entry("delete", &service, &account)?.delete_credential() {
            Ok(()) => Ok(true),
            Err(keyring::Error::NoEntry) => Ok(false),
            Err(e) => Err(IpcError::new("keyring", "delete", e).into_string()),
        }
    }
}

/// Construct a `keyring::Entry`, surfacing the `(service, account)`
/// validation in one place. Pulled out of the macro-generated arms so
/// each handler can spell its own method name in the error path
/// (matches the pre-U10 message shape: `keyring.<method>: ...`).
fn new_entry(method: &str, service: &str, account: &str) -> Result<Entry, String> {
    if service.is_empty() || account.is_empty() {
        return Err(IpcError::new(
            "keyring",
            method,
            "'service' and 'account' must not be empty",
        )
        .into_string());
    }
    Entry::new(service, account).map_err(|e| IpcError::new("keyring", method, e).into_string())
}
